<script setup lang="ts">
import type { ProductDraft } from '@/Types/financial';
import { inputValue } from '@/Utils/input';
const props = defineProps<{ form: ProductDraft; errors: Partial<Record<keyof ProductDraft, string>>; prefix: string; referenceRate: string; workingCurrency: string }>();
const setMode = (event: Event) => {
    props.form.rate_mode = inputValue(event) === 'paid' ? 'paid' : 'estimated';
    if (props.form.rate_mode === 'paid' && ['trip-reference','legacy-unverified'].includes(props.form.rate_source)) props.form.rate_source = '';
};
</script>
<template>
    <div class="f-form-grid">
        <div class="f-field"><label :for="`${prefix}-mode`">Conversión de la compra</label><select :id="`${prefix}-mode`" :aria-invalid="!!errors.rate_mode" :aria-describedby="errors.rate_mode ? `${prefix}-mode-error` : undefined" class="f-input" :value="form.rate_mode" @change="setMode"><option value="estimated">Estimado: tasa de referencia</option><option value="paid">Pagado: tasa histórica</option></select><p class="f-hint">{{ form.rate_mode === 'paid' ? 'La tasa histórica se conserva al revaluar. Corregir el pago requiere revisar sus datos originales.' : `Referencia: ${form.moneda === 'CLP' ? '1' : referenceRate} CLP / ${form.moneda}.` }}</p><span :id="`${prefix}-mode-error`" class="f-field-error">{{ errors.rate_mode }}</span></div>
        <template v-if="form.rate_mode === 'paid'"><div class="f-field"><label :for="`${prefix}-rate`">Tasa histórica · CLP / {{ form.moneda }}</label><input :id="`${prefix}-rate`" :aria-invalid="!!errors.applied_rate" :aria-describedby="errors.applied_rate ? `${prefix}-rate-error` : undefined" class="f-input" type="number" :value="form.applied_rate" @input="form.applied_rate = inputValue($event)" min="0.00000001" max="1000000" step="0.00000001" required /><p v-if="form.moneda === 'CLP'" class="f-hint">Una compra en CLP utiliza tasa 1.</p><span :id="`${prefix}-rate-error`" class="f-field-error">{{ errors.applied_rate }}</span></div><div class="f-field"><label :for="`${prefix}-source`">Fuente de la tasa del pago</label><input :id="`${prefix}-source`" :aria-invalid="!!errors.rate_source" :aria-describedby="errors.rate_source ? `${prefix}-source-error` : undefined" class="f-input" v-model="form.rate_source" maxlength="255" required placeholder="Comprobante bancario, factura…" /><span :id="`${prefix}-source-error`" class="f-field-error">{{ errors.rate_source }}</span></div><div class="f-field"><label :for="`${prefix}-date`">Fecha del pago de la compra</label><input :id="`${prefix}-date`" :aria-invalid="!!errors.rate_date" :aria-describedby="errors.rate_date ? `${prefix}-date-error` : undefined" class="f-input" type="date" v-model="form.rate_date" required /><span :id="`${prefix}-date-error`" class="f-field-error">{{ errors.rate_date }}</span></div></template>
        <div class="f-field"><label :for="`${prefix}-weight`">Peso total de la línea · kg</label><input :id="`${prefix}-weight`" :aria-invalid="!!errors.weight" :aria-describedby="errors.weight ? `${prefix}-weight-error` : undefined" class="f-input" type="number" :value="form.weight" @input="form.weight = inputValue($event)" min="0" max="999999999" step="0.00000001" placeholder="Sin dato" /><span :id="`${prefix}-weight-error`" class="f-field-error">{{ errors.weight }}</span><p class="f-hint">Peso de todas las unidades de esta línea.</p></div>
        <div class="f-field"><label :for="`${prefix}-volume`">Volumen total de la línea · m³</label><input :id="`${prefix}-volume`" :aria-invalid="!!errors.volume" :aria-describedby="errors.volume ? `${prefix}-volume-error` : undefined" class="f-input" type="number" :value="form.volume" @input="form.volume = inputValue($event)" min="0" max="999999999" step="0.00000001" placeholder="Sin dato" /><span :id="`${prefix}-volume-error`" class="f-field-error">{{ errors.volume }}</span><p class="f-hint">Volumen de todas las unidades de esta línea.</p></div>
    </div>
</template>
